window.__finlexDocLoaded(221,{"id":221,"articles":[{"id":5454,"no":"问1","heading":"问：根据《企业会计准则解释第20号》，当一种货币不可兑换为另一种货币时，企业可采用其他目的下的可观察汇率、可兑换性恢复后的首个汇率或其他估计方法对计量日的即期汇率进行估计。对于前述估计方法的选用是否有优先次序？","text":"【发布日期：2026-07-23】\n答：根据《企业会计准则解释第20号》，当一种货币不可兑换为另一种货币时，企业应当对计量日的即期汇率进行估计，使其能够如实反映在当前主要经济状况下市场参与者在计量日进行的有序兑换交易所采用的汇率；在满足前述要求的情况下，企业可采用未经调整的可观察汇率（包括其他目的下的可观察汇率、可兑换性恢复后的首个汇率）或其他估计方法对计量日的即期汇率进行估计。对于前述估计方法的选择无优先次序要求，企业应当结合业务实际情况和所处经济环境等合理选择适当的方法，并确保依照该方法估计的即期汇率能够满足“如实反映在当前主要经济状况下市场参与者在计量日进行的有序兑换交易所采用的汇率”等要求。此外，企业还需根据《企业会计准则解释第20号》有关规定在附注中披露所采用的即期汇率及其估计过程的相关信息。","seq":0,"links":[{"doc_id":19,"tier":"L1","score":94,"rel_kind":"companion","target_seq":0,"target_art_no":"第一条","dir":"out","note":"核心配套：财政部会计司官方实施问答"},{"doc_id":19,"tier":"L1","score":94,"rel_kind":"companion","target_seq":2,"target_art_no":"第三条","dir":"out","note":"实施问答（问1）：锚定第三条（条文主题匹配）"},{"doc_id":54,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一项","dir":"out","note":"正文显式引用《企业会计准则解释第20号》"}]},{"id":5455,"no":"问2","heading":"问：外币预收账款和预付账款是货币性项目还是非货币性项目，上述项目在资产负债表日是否会产生汇兑损益？","text":"【发布日期：2021-03-02】\n答：根据外币折算准则第十一条，货币性项目，是指企业持有的货币资金和将以固定或可确定的金额收取的资产或偿付的负债；非货币性项目是指货币性项目以外的项目。在资产负债表日，以历史成本计量的外币非货币性项目，仍采用交易发生日的即期汇率折算，不改变其记账本位币金额。\n外币预收账款和预付账款均不满足货币性项目的定义，属于以历史成本计量的外币非货币性项目，企业在资产负债表日应当采用交易发生日的即期汇率折算，不产生汇兑损益。","seq":1,"links":[{"doc_id":19,"tier":"L1","score":94,"rel_kind":"companion","target_seq":10,"target_art_no":"第十一条","dir":"out","note":"实施问答（问2）：锚定第十一条（即期汇率）"}]}]});
